    {
      "section": "V1",
      "lyrics": [
        "淡い月に見とれてしまうから",
        "暗い足元も見えずに",
        "転んだことに気がつけないまま",
        "遠い夜の星が滲む",
        "したいことが見つけられないから",
        "急いだ振り 俯くまま",
        "転んだ後に笑われてるもの",
        "気づかない振りをするのだ"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "形のない歌で朝を描いたまま",
        "浅い浅い夏の向こうに",
        "冷たくない君の手のひらが見えた",
        "淡い空 明けの蛍"
      ]
    }
  ],
