  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "用一首没有词的歌 把黎明画在手心"
        },
        {
          "id": "C1-02",
          "zh": "浅夏末 薄如水 那头浮起天光"
        },
        {
          "id": "C1-03",
          "zh": "我看见你摊开手掌 那一点不冷的温度"
        },
        {
          "id": "C1-04",
          "zh": "淡色的天空 有只萤火在晃"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "无形的歌 描着黎明 一直唱到天亮"
        },
        {
          "id": "C1-02",
          "zh": "浅浅的 浅浅的 夏天那头"
        },
        {
          "id": "C1-03",
          "zh": "我看见你 不冷的手掌 在微微发光"
        },
        {
          "id": "C1-04",
          "zh": "淡色天空 破晓的萤火"
        }
      ]
    }
  ]
}

